const envelope = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const reference = String(envelope.ref_mission || envelope.reference_mission || envelope.reference || '').replace(/[=\s]/g, '').trim().toUpperCase();
if (!/^MIS-2026-\d{4}$/.test(reference)) throw new Error('Référence de mission absente ou invalide : format attendu MIS-2026-XXXX.');
const expediteur = String(envelope.expediteur || '').replace(/\D/g, '');
if (!/^\d{7,15}$/.test(expediteur)) throw new Error('Numéro WhatsApp expéditeur absent ou invalide.');
const nom_expediteur = String(envelope.nom_expediteur || '').trim();
const message = String(envelope.texte_message || envelope.message || '').trim();
if (!message) throw new Error('Message brut du client absent.');
if (message.length > 4096) throw new Error('Le message client dépasse la taille maximale autorisée de 4096 caractères.');
const escapeHtml = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const messageHtml = escapeHtml(message).replace(/\r?\n/g, '<br>');
return { json: { expediteur, nom_expediteur, message, message_html: messageHtml, reference } };

const response = $json;
const reference = $('Valider Handoff Option B').first().json.reference;
const candidates = [response, response.data].filter(value => value && typeof value === 'object');
let records = [];
for (const candidate of candidates) {
  if (Array.isArray(candidate)) { records = candidate; break; }
  for (const key of ['records', 'list', 'data']) {
    if (Array.isArray(candidate[key])) { records = candidate[key]; break; }
  }
  if (records.length) break;
}
const normalized = records.map(record => record && record.fields && typeof record.fields === 'object' ? { ...record, ...record.fields } : record);
const matches = normalized.filter(record => String(record?.Code_Mission || '').replace(/[=\s]/g, '').trim().toUpperCase() === reference);
if (matches.length !== 1) throw new Error('La mission ' + reference + ' doit correspondre à exactement un enregistrement NocoDB ; résultats : ' + matches.length + '.');
const recordId = matches[0].Id ?? matches[0].id;
if (recordId === undefined || recordId === null || recordId === '') throw new Error('Identifiant primaire absent de l’enregistrement NocoDB pour ' + reference + '.');
return { json: { reference, record_id: recordId } };

const cleanRef = String($json.query?.ref ?? $json.query?.reference ?? '').replace(/^[=\s]+/, '').trim().toUpperCase();
if (!/^MIS-2026-\d{4}$/.test(cleanRef)) throw new Error('Référence de mission absente ou invalide : format attendu MIS-2026-XXXX.');
return { json: { reference: cleanRef } };

const response = $json;
const reference = $('Valider Référence Statut').first().json.reference;
const candidates = [response, response.data].filter(value => value && typeof value === 'object');
let records = [];
for (const candidate of candidates) {
  if (Array.isArray(candidate)) { records = candidate; break; }
  for (const key of ['records', 'list', 'data']) {
    if (Array.isArray(candidate[key])) { records = candidate[key]; break; }
  }
  if (records.length) break;
}
const normalized = records.map(record => record && record.fields && typeof record.fields === 'object' ? { ...record, ...record.fields } : record);
const mission = normalized.find(record => String(record?.Code_Mission || '').replace(/[=\s]/g, '').trim().toUpperCase() === reference);
const date = mission ? mission.Date_Ancrage || mission.CreatedAt || mission.created_at || mission.Date_Creation || mission.Date || null : null;
return { json: {
  success: true,
  reference,
  found: Boolean(mission),
  statut: mission ? String(mission.Statut || 'Diagnostic Initial') : 'Diagnostic Initial',
  secteur: mission ? String(mission.Secteur || 'Agro-industrie et souveraineté alimentaire') : 'Agro-industrie et souveraineté alimentaire',
  palier: mission ? String(mission.Palier || 'mandat') : 'mandat',
  sha256_hash: mission ? String(mission.Empreinte_SHA256 || mission.Contrat_Hash_Ref || '') : '',
  expert_assigne: mission ? mission.Expert_Assigne || null : null,
  date: date ? String(date) : null
} };
